solution.solution.cpp:
#include <string>

// The value of a string of binary digits, most significant bit first.
unsigned int fromBinary(const std::string& bits)
{
    unsigned int value{ 0 };
    for (char bit : bits)
    {
        value *= 2;                 // everything so far moves one place to the left
        if (bit == '1') value += 1;
    }
    return value;
}

unitTests:
TEST("single bits") { CHECK_EQ(fromBinary("0"), 0u); CHECK_EQ(fromBinary("1"), 1u); }
TEST("four bits") { CHECK_EQ(fromBinary("1010"), 10u); CHECK_EQ(fromBinary("1111"), 15u); }
TEST("a whole byte") { CHECK_EQ(fromBinary("01001101"), 77u); CHECK_EQ(fromBinary("11111111"), 255u); }
TEST("leading zeros change nothing") { CHECK_EQ(fromBinary("00000001"), 1u); }
TEST("sixteen bits") { CHECK_EQ(fromBinary("1011111011101111"), 48879u); }
TEST("an empty string is zero") { CHECK_EQ(fromBinary(""), 0u); }

